window.KhaemenesBiology10QuestionBank=[{"id":"bio-001","prompt":"Which property of water most directly explains capillary action in narrow plant vessels?","options":["Water has no mass","Cohesion and adhesion arise from polarity","Water is always neutral in pH","Water contains carbon"],"answer":1,"explanation":"Polarity supports hydrogen bonding, cohesion, and adhesion.","week":2,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Week 02"},{"id":"bio-002","prompt":"Why can high temperature reduce enzyme activity?","options":["It always removes substrate","It can disrupt the enzyme's three-dimensional structure","It converts proteins into DNA","It increases chromosome number"],"answer":1,"explanation":"Excess heat can alter protein structure and active-site geometry.","week":4,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Week 04"},{"id":"bio-003","prompt":"A cell with a high surface-area-to-volume ratio generally has what advantage?","options":["Faster exchange relative to its volume","More chromosomes","No need for ATP","Unlimited size"],"answer":0,"explanation":"More membrane area is available per unit volume for exchange.","week":6,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Week 06"},{"id":"bio-004","prompt":"Osmosis is best described as","options":["movement of water across a selectively permeable membrane","active pumping of any solute","cell division","protein synthesis"],"answer":0,"explanation":"Osmosis concerns water movement across selectively permeable membranes.","week":6,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Week 06"},{"id":"bio-005","prompt":"Which organelle is most directly associated with ATP production during aerobic respiration?","options":["Golgi apparatus","Mitochondrion","Nucleus","Lysosome"],"answer":1,"explanation":"Mitochondria carry out major stages of aerobic cellular respiration.","week":10,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Week 10"},{"id":"bio-006","prompt":"Photosynthesis primarily stores energy by","options":["converting chemical energy to sound","building energy-rich organic molecules using light energy","destroying carbon atoms","eliminating all entropy"],"answer":1,"explanation":"Light energy is transformed into chemical energy in organic molecules.","week":9,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Week 09"},{"id":"bio-007","prompt":"Cellular respiration and photosynthesis are linked because","options":["products of one process can serve as reactants for the other","both occur only in animals","neither involves redox reactions","both create matter from nothing"],"answer":0,"explanation":"Matter cycles through complementary biochemical pathways.","week":11,"type":"model","difficulty":"core","source":"H1-model","topic":"Week 11"},{"id":"bio-008","prompt":"ATP is useful to cells because it","options":["is the only molecule containing phosphorus","couples energy-releasing and energy-requiring processes","stores hereditary information","replaces enzymes"],"answer":1,"explanation":"ATP serves as an energy-coupling molecule.","week":10,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Week 10"},{"id":"bio-009","prompt":"A receptor protein contributes to cell signaling by","options":["recognizing particular signals and initiating a response pathway","replicating DNA directly","forming every cell membrane lipid","making all signals identical"],"answer":0,"explanation":"Receptors provide specificity in signal reception.","week":13,"type":"model","difficulty":"core","source":"H1-model","topic":"Week 13"},{"id":"bio-010","prompt":"Negative feedback tends to","options":["push a regulated variable farther from its functional range","reduce a deviation from a regulated range","stop all biological change","increase chromosome number"],"answer":1,"explanation":"Negative feedback counteracts deviations.","week":14,"type":"model","difficulty":"core","source":"H1-model","topic":"Week 14"},{"id":"bio-011","prompt":"Mitosis contributes to growth by producing","options":["four genetically varied haploid cells","two daughter cells that usually retain chromosome number","only gametes","new alleles by independent assortment"],"answer":1,"explanation":"Mitosis generally maintains chromosome number in daughter cells.","week":15,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Week 15"},{"id":"bio-012","prompt":"A high mitotic index in prepared tissue indicates","options":["a larger fraction of cells observed in mitosis","every cell has mutated","photosynthesis is faster","meiosis is occurring"],"answer":0,"explanation":"Mitotic index is the fraction of observed cells in mitosis.","week":15,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Week 15"},{"id":"bio-013","prompt":"Crossing over during meiosis contributes to","options":["genetic variation among gametes","DNA elimination from all cells","identical gametes","doubling chromosome number"],"answer":0,"explanation":"Recombination produces new combinations of alleles.","week":19,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Week 19"},{"id":"bio-014","prompt":"A Punnett square predicts","options":["guaranteed outcomes for a family","probabilities under a genetic model","environmental effects with certainty","the exact DNA sequence of an organism"],"answer":1,"explanation":"Punnett squares represent probabilities, not guarantees.","week":20,"type":"model","difficulty":"core","source":"H2-model","topic":"Week 20"},{"id":"bio-015","prompt":"Polygenic traits are typically influenced by","options":["only one allele","multiple genes and often environmental factors","no genetic information","only mitochondrial DNA"],"answer":1,"explanation":"Many genes and environmental context can influence quantitative traits.","week":22,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Week 22"},{"id":"bio-016","prompt":"DNA replication relies on complementary base pairing because","options":["each strand can guide construction of a new partner strand","proteins replace nucleotides","RNA is never involved in cells","chromosomes disappear"],"answer":0,"explanation":"Complementarity lets each parental strand serve as a template.","week":23,"type":"model","difficulty":"core","source":"H2-model","topic":"Week 23"},{"id":"bio-017","prompt":"During translation, ribosomes primarily","options":["read mRNA codons to assemble a polypeptide","copy DNA into DNA","digest all proteins","separate homologous chromosomes"],"answer":0,"explanation":"Ribosomes translate mRNA information into amino-acid sequence.","week":24,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Week 24"},{"id":"bio-018","prompt":"A mutation can be silent when","options":["it does not change the encoded amino acid","it removes every chromosome","it occurs only outside DNA","it always increases fitness"],"answer":0,"explanation":"Redundancy in the genetic code can yield no amino-acid change.","week":24,"type":"model","difficulty":"core","source":"H2-model","topic":"Week 24"},{"id":"bio-019","prompt":"Gene regulation helps explain why","options":["different cell types express different proteins despite similar genomes","all cells have different DNA sequences","genes never respond to environment","ribosomes store genes"],"answer":0,"explanation":"Cell identity depends strongly on regulated expression.","week":25,"type":"model","difficulty":"core","source":"H2-model","topic":"Week 25"},{"id":"bio-020","prompt":"A responsible genomics program should explicitly consider","options":["privacy, consent, uncertainty, and potential misuse","only file size","eliminating all uncertainty from prediction","hiding methods"],"answer":0,"explanation":"Genetic information raises major privacy and consent issues.","week":26,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Week 26"},{"id":"bio-021","prompt":"Multiple lines of evidence for evolutionary relationships are strongest when they","options":["independently converge on compatible patterns","all come from one diagram","exclude molecular evidence","avoid testable predictions"],"answer":0,"explanation":"Independent evidence streams increase explanatory support.","week":27,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Week 27"},{"id":"bio-022","prompt":"Natural selection requires","options":["heritable variation and differences in reproductive success","individuals changing genes because they need to","no environmental interaction","equal reproduction by all organisms"],"answer":0,"explanation":"Selection changes populations when heritable differences affect reproductive success.","week":29,"type":"model","difficulty":"core","source":"H2-model","topic":"Week 29"},{"id":"bio-023","prompt":"Allele frequency refers to","options":["the proportion of a particular allele in a population gene pool","the number of organelles in a cell","the speed of an enzyme","the age of a fossil"],"answer":0,"explanation":"Population genetics tracks allele proportions.","week":28,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Week 28"},{"id":"bio-024","prompt":"Speciation involves","options":["the evolution of reproductive isolation between populations","mitosis in body cells","photosynthesis","only short-term weather change"],"answer":0,"explanation":"Reproductive isolation is central to lineage divergence.","week":30,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Week 30"},{"id":"bio-025","prompt":"A phylogenetic tree is best interpreted as","options":["a testable model of hypothesized relationships","a literal ladder of progress","a measure of individual fitness","a food web"],"answer":0,"explanation":"Phylogenies are evidence-based models of relationships.","week":30,"type":"model","difficulty":"core","source":"H2-model","topic":"Week 30"},{"id":"bio-026","prompt":"Energy pyramids narrow at higher trophic levels largely because","options":["energy transfers are inefficient and much energy dissipates as heat","matter disappears","predators make energy","producers contain no energy"],"answer":0,"explanation":"Only a fraction of energy is transferred to the next trophic level.","week":31,"type":"quantitative","difficulty":"core","source":"H2-quantitative","topic":"Week 31"},{"id":"bio-027","prompt":"In ecosystems, matter generally","options":["cycles through reservoirs while energy flows through the system","is destroyed at each trophic level","moves only through organisms","never enters the atmosphere"],"answer":0,"explanation":"Matter cycles while usable energy flows and dissipates.","week":32,"type":"model","difficulty":"core","source":"H2-model","topic":"Week 32"},{"id":"bio-028","prompt":"Carrying capacity is","options":["the population size an environment can sustain under particular conditions","a fixed universal number for a species","the number of chromosomes","a measure of mutation rate"],"answer":0,"explanation":"Carrying capacity depends on resources and conditions.","week":33,"type":"model","difficulty":"core","source":"H2-model","topic":"Week 33"},{"id":"bio-029","prompt":"Biodiversity can increase resilience because","options":["multiple species/functions can provide response diversity","all species respond identically","diversity eliminates disturbance","diversity prevents evolution"],"answer":0,"explanation":"Functional and response diversity can support system resilience.","week":34,"type":"model","difficulty":"core","source":"H2-model","topic":"Week 34"},{"id":"bio-030","prompt":"A strong biological capstone claim should","options":["connect evidence to reasoning and state limitations","hide uncertainty","avoid quantitative evidence","treat correlation as proof of causation"],"answer":0,"explanation":"Scientific argumentation requires evidence, reasoning, and limits.","week":35,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Week 35"},{"id":"bio-031","prompt":"Two teams measure the same specimen. Team A reports 10.1, 10.2, 10.1 cm and Team B reports 10.8, 10.9, 10.8 cm. What is the strongest next step?","options":["Conclude the specimen changed between teams","Standardize measurement endpoints and repeat with the same protocol","Average all six values and ignore team identity","Discard the lower values"],"answer":1,"explanation":"Within-team precision is high, but the between-team difference suggests a possible systematic measurement difference that should be tested.","week":1,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Week 01"},{"id":"bio-032","prompt":"A measured quantity rises from 40 to 50 units. What is the percent change relative to the original value?","options":["10%","20%","25%","40%"],"answer":2,"explanation":"Percent change is (50−40)/40 × 100 = 25%.","week":1,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Week 01"},{"id":"bio-033","prompt":"Which observation best supports hydrogen bonding as an explanation for water's unusual cohesion?","options":["Water molecules contain carbon atoms","Water shows strong surface tension compared with similar-sized nonpolar molecules","All liquids climb paper equally","Water has no intermolecular forces"],"answer":1,"explanation":"Comparative physical behavior can support the role of polarity and hydrogen bonding.","week":2,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Week 02"},{"id":"bio-034","prompt":"A food-label model shows 20 g carbohydrate, 10 g protein, and 5 g fat. Which statement is most scientifically defensible?","options":["The label alone identifies the food's complete biological effect","The macromolecule quantities can be compared, but digestion and health effects require additional evidence","Protein and carbohydrate are chemically identical","Fat contains no carbon"],"answer":1,"explanation":"Composition data support composition claims, not complete physiological conclusions.","week":3,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Week 03"},{"id":"bio-035","prompt":"A model enzyme reaction produces 18 units in 3 min without catalyst and 54 units in 3 min with catalyst. What are the average rates?","options":["6 and 18 units/min","18 and 54 units/min","3 and 9 units/min","21 and 57 units/min"],"answer":0,"explanation":"Rate equals change divided by elapsed time: 18/3=6 and 54/3=18 units/min.","week":4,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Week 04"},{"id":"bio-036","prompt":"A prepared micrograph scale bar representing 20 μm measures 4 cm on paper. A cell measures 6 cm on the same print. Estimated actual cell length?","options":["13.3 μm","20 μm","30 μm","120 μm"],"answer":2,"explanation":"The cell is 6/4=1.5 times the scale bar, so 1.5×20 μm=30 μm.","week":5,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Week 05"},{"id":"bio-037","prompt":"For a cube-shaped cell model, which change most increases surface-area-to-volume ratio?","options":["Increasing side length from 1 to 4","Decreasing side length from 4 to 1","Doubling both surface area and volume independently","Removing the membrane"],"answer":1,"explanation":"Smaller cubes have more surface area per unit volume.","week":6,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Week 06"},{"id":"bio-038","prompt":"Which evidence most strongly supports the endosymbiotic origin of mitochondria?","options":["Mitochondria are always the largest organelles","They contain bacterial-like ribosomes and their own circular DNA, among other converging features","They are found only in plants","They contain the cell's nuclear chromosomes"],"answer":1,"explanation":"Multiple bacterial-like features provide converging evidence for endosymbiotic ancestry.","week":7,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Week 07"},{"id":"bio-039","prompt":"Two cell types share nearly the same genome but produce different proteins. Which model best explains the difference?","options":["Every differentiated cell loses most genes","Different regulatory programs activate different genes","Ribosomes rewrite DNA sequence in each tissue","Cell shape determines nucleotide order"],"answer":1,"explanation":"Differential gene expression is central to cell specialization.","week":8,"type":"model","difficulty":"core","source":"H1-model","topic":"Week 08"},{"id":"bio-040","prompt":"Photosynthetic rate increases with light intensity and then plateaus. What is the strongest interpretation?","options":["Light is no longer the only limiting factor at high intensity","Photosynthesis has stopped permanently","Carbon atoms are being destroyed","More light must always decrease rate"],"answer":0,"explanation":"A plateau is consistent with another factor becoming limiting or the system approaching capacity under those conditions.","week":9,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Week 09"},{"id":"bio-041","prompt":"A respirometry model reports oxygen consumption of 12 mL in 6 min for 2 g tissue. What is the mass-specific rate?","options":["1 mL O₂ min⁻¹ g⁻¹","2 mL O₂ min⁻¹ g⁻¹","4 mL O₂ min⁻¹ g⁻¹","12 mL O₂ min⁻¹ g⁻¹"],"answer":0,"explanation":"12 mL ÷ 6 min ÷ 2 g = 1 mL O₂ min⁻¹ g⁻¹.","week":10,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Week 10"},{"id":"bio-042","prompt":"Why is atom accounting useful when comparing photosynthesis and respiration?","options":["It tests whether matter is conserved through the simplified reactions","It proves energy is recycled","It shows atoms disappear during metabolism","It replaces all experimental evidence"],"answer":0,"explanation":"Tracking atoms checks conservation of matter across reaction models.","week":11,"type":"model","difficulty":"core","source":"H1-model","topic":"Week 11"},{"id":"bio-043","prompt":"Organism A produces 30 mL CO₂/h at 10 g mass; B produces 40 mL CO₂/h at 20 g. Which has the higher mass-specific rate?","options":["A","B","They are equal","Cannot be compared even after normalization"],"answer":0,"explanation":"A: 3 mL/h/g; B: 2 mL/h/g, so A has the higher normalized rate.","week":12,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Week 12"},{"id":"bio-044","prompt":"A dose-response curve rises sharply and then plateaus. Which claim is justified?","options":["The response increases over part of the tested dose range and approaches a maximum under those conditions","The receptor mechanism is proven from the curve alone","Every cell has the same receptor number","Higher doses can never have side effects"],"answer":0,"explanation":"The graph supports a bounded response pattern, not a complete molecular mechanism.","week":13,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Week 13"},{"id":"bio-045","prompt":"A regulated variable has reference value 50 and rises to 58 before returning to 50. Maximum percent deviation?","options":["8%","16%","50%","58%"],"answer":1,"explanation":"Deviation is 8; 8/50×100=16%.","week":14,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Week 14"},{"id":"bio-046","prompt":"A diploid cell has 8 chromosomes in G1. Immediately after S phase, how many chromosomes and sister chromatids?","options":["8 chromosomes and 8 chromatids","8 chromosomes and 16 chromatids","16 chromosomes and 16 chromatids","16 chromosomes and 8 chromatids"],"answer":1,"explanation":"Replication doubles DNA/chromatid count while chromosome count remains 8 until sister chromatids separate.","week":15,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Week 15"},{"id":"bio-047","prompt":"Two cell lines differ in proliferation rate and in a regulatory gene variant. What evidence would most strengthen a causal claim?","options":["A larger color difference in a graph","Restoring the regulator in the variant line and testing whether the phenotype shifts as predicted","Repeating the same correlation statement","Removing the control group"],"answer":1,"explanation":"A rescue-style comparison tests whether changing the suspected factor changes the phenotype in the predicted direction.","week":16,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Week 16"},{"id":"bio-048","prompt":"A student removes an outlier only because it weakens the expected result. What is the best scientific response?","options":["Keep or exclude it using a pre-stated defensible rule and preserve the raw value","Delete it silently","Change the hypothesis after seeing the graph","Round it until it fits"],"answer":0,"explanation":"Data exclusions require transparent rules tied to measurement quality or design, not preferred conclusions.","week":17,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Week 17"},{"id":"bio-049","prompt":"For a species with n=5 homologous chromosome pairs, how many whole-chromosome combinations are possible from independent assortment alone in the simple 2^n model?","options":["10","25","32","64"],"answer":2,"explanation":"2^5 = 32 combinations.","week":19,"type":"quantitative","difficulty":"core","source":"H2-quantitative","topic":"Week 19"},{"id":"bio-050","prompt":"A simple Aa × Aa model predicts what expected fraction of aa offspring?","options":["1/4","1/2","3/4","1"],"answer":0,"explanation":"The four equally likely genotype cells are AA, Aa, Aa, aa.","week":20,"type":"quantitative","difficulty":"core","source":"H2-quantitative","topic":"Week 20"},{"id":"bio-051","prompt":"Two independent events have probabilities 1/2 and 1/4. Probability both occur?","options":["1/8","1/4","1/2","3/4"],"answer":0,"explanation":"For independent events that must both occur, multiply: 1/2×1/4=1/8.","week":21,"type":"quantitative","difficulty":"core","source":"H2-quantitative","topic":"Week 21"},{"id":"bio-052","prompt":"Two genotypes show crossing reaction-norm lines across environments. What does that pattern support?","options":["A gene–environment interaction in the measured phenotype","No environmental effect","Identical genotype responses","A guaranteed personal outcome"],"answer":0,"explanation":"Nonparallel or crossing reaction norms are consistent with genotype effects depending on environment.","week":22,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Week 22"},{"id":"bio-053","prompt":"If double-stranded DNA contains 24% cytosine, approximately what percentage is adenine?","options":["24%","26%","48%","52%"],"answer":1,"explanation":"G≈24%, leaving 52% for A+T, so A≈26%.","week":23,"type":"quantitative","difficulty":"core","source":"H2-quantitative","topic":"Week 23"},{"id":"bio-054","prompt":"A one-base insertion occurs early in a protein-coding region. Why can its effect be large?","options":["It can shift the downstream reading frame","It always repairs the gene","It converts RNA directly into DNA","It guarantees a beneficial phenotype"],"answer":0,"explanation":"A non-triplet insertion can change downstream codon grouping.","week":24,"type":"model","difficulty":"core","source":"H2-model","topic":"Week 24"},{"id":"bio-055","prompt":"Normalized RNA expression rises from 20 to 80 units. Fold change?","options":["0.25-fold","2-fold","4-fold","60-fold"],"answer":2,"explanation":"80/20=4-fold.","week":25,"type":"quantitative","difficulty":"core","source":"H2-quantitative","topic":"Week 25"},{"id":"bio-056","prompt":"Why is a negative control important in a conceptual PCR assay?","options":["It helps detect contamination or nonspecific signal when target template should be absent","It guarantees every primer is perfect","It identifies a person's ancestry","It doubles target DNA"],"answer":0,"explanation":"A negative control tests whether signal appears even without the intended target/template condition.","week":26,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Week 26"},{"id":"bio-057","prompt":"In 100 diploid organisms, allele A has 120 copies among 200 total allele copies. Frequency of A?","options":["0.40","0.50","0.60","1.20"],"answer":2,"explanation":"Allele frequency is 120/200=0.60.","week":28,"type":"quantitative","difficulty":"core","source":"H2-quantitative","topic":"Week 28"},{"id":"bio-058","prompt":"Producer production is 8,000 kJ m⁻² yr⁻¹ and herbivore production is 960 kJ m⁻² yr⁻¹. Ecological efficiency?","options":["8%","10%","12%","96%"],"answer":2,"explanation":"960/8000×100=12%.","week":31,"type":"quantitative","difficulty":"core","source":"H2-quantitative","topic":"Week 31"},{"id":"bio-059","prompt":"A reservoir contains 900 units and has an outgoing flux of 45 units/year under steady-state assumptions. Approximate residence time?","options":["5 years","20 years","45 years","900 years"],"answer":1,"explanation":"Residence time≈reservoir/flux=900/45=20 years.","week":32,"type":"quantitative","difficulty":"core","source":"H2-quantitative","topic":"Week 32"},{"id":"bio-060","prompt":"In a logistic model with carrying capacity K=1,000 and population N=900, what is the density factor 1−N/K?","options":["0.1","0.9","1.0","100"],"answer":0,"explanation":"1−900/1000=0.1.","week":33,"type":"quantitative","difficulty":"core","source":"H2-quantitative","topic":"Week 33"},{"id":"bio-sup-w01-concept","week":1,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Readiness, Safety & Quantitative Biology","prompt":"Which statement best describes good quantitative biological measurement?","options":["Use appropriate units, repeat measurements, report uncertainty, and follow reproducible procedures.","One precise-looking number is enough even without units.","Measurement uncertainty should be hidden if results match expectations.","Safety procedures can be skipped when measurements are simple."],"answer":0,"explanation":"Reliable biological measurement requires units, replication, uncertainty, reproducibility, and safety."},{"id":"bio-sup-w01-evidence","week":1,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Readiness, Safety & Quantitative Biology","prompt":"Which evidence most strongly supports that a measurement procedure is reliable?","options":["Repeated measurements show a consistent pattern with documented variation and the same protocol.","One result matches the expected answer.","A value is reported to many decimal places.","Different observers use different endpoints without comparison."],"answer":0,"explanation":"Replication with documented variation and a consistent protocol is stronger evidence of reliability."},{"id":"bio-sup-w01-model","week":1,"type":"model","difficulty":"core","source":"H1-model","topic":"Readiness, Safety & Quantitative Biology","prompt":"Which statement correctly limits interpretation of a readiness diagnostic?","options":["It identifies current skill gaps but should not be treated as a permanent label of ability.","A low score proves a student cannot learn the skill.","One diagnostic result should determine all future course placement permanently.","Readiness scores are independent of prior experience and testing conditions."],"answer":0,"explanation":"Readiness diagnostics are provisional evidence of current skills, not permanent labels."},{"id":"bio-sup-w02-concept","week":2,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Water, Carbon & the Chemistry of Life","prompt":"Which property of water is most directly explained by its polarity and hydrogen bonding?","options":["Strong cohesion and unusual solvent behavior","Complete inability to dissolve ionic substances","Absence of intermolecular forces","Chemical identity with nonpolar hydrocarbons"],"answer":0,"explanation":"Water's polarity and hydrogen bonding help explain cohesion and solvent properties."},{"id":"bio-sup-w02-evidence","week":2,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Water, Carbon & the Chemistry of Life","prompt":"Which comparison would best test a claim that polarity affects solubility?","options":["Compare solubility of the same solute in solvents with different polarity while controlling temperature.","Compare different solutes in different solvents at different temperatures.","Measure only solvent color.","Assume a substance is polar because it dissolves once."],"answer":0,"explanation":"Controlled comparison across solvent polarity directly tests its effect on solubility."},{"id":"bio-sup-w02-model","week":2,"type":"model","difficulty":"core","source":"H1-model","topic":"Water, Carbon & the Chemistry of Life","prompt":"Which statement correctly limits the rule 'like dissolves like'?","options":["It is useful, but molecular size, functional groups, and competing interactions also affect solubility.","It perfectly predicts every solubility outcome.","Polar substances can never dissolve in partly nonpolar solvents.","Temperature and concentration never matter."],"answer":0,"explanation":"Polarity is important but not the only determinant of solubility."},{"id":"bio-sup-w03-concept","week":3,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Macromolecules & Structure–Function","prompt":"Which statement best describes the structure–function relationship in macromolecules?","options":["Monomer composition, bonding, functional groups, and three-dimensional shape influence biological function.","Molecule size alone determines function.","All proteins with the same mass have the same function.","Carbohydrates, proteins, lipids, and nucleic acids have identical chemical behavior."],"answer":0,"explanation":"Macromolecular function depends on detailed chemical structure and shape, not size alone."},{"id":"bio-sup-w03-evidence","week":3,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Macromolecules & Structure–Function","prompt":"Which evidence most strongly supports a structure–function claim for a protein?","options":["A controlled structural change is followed by a reproducible change in protein function.","Two proteins have similar colors.","A protein is large.","One structural model looks more complex."],"answer":0,"explanation":"A controlled structural change linked to a functional change directly supports structure–function reasoning."},{"id":"bio-sup-w03-model","week":3,"type":"model","difficulty":"core","source":"H1-model","topic":"Macromolecules & Structure–Function","prompt":"Which statement correctly limits simple macromolecule classification?","options":["Classifying molecules only by size can miss important differences in functional groups and three-dimensional structure.","All large molecules have the same biological role.","Molecular shape never affects function.","Functional groups matter only in inorganic compounds."],"answer":0,"explanation":"Size alone is an incomplete predictor of macromolecule chemistry and function."},{"id":"bio-sup-w03-quantitative","week":3,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Macromolecules & Structure–Function","prompt":"A sample contains 24 g protein, 36 g carbohydrate, and 40 g lipid. What percent of the sample is protein?","options":["24%","40%","60%","76%"],"answer":0,"explanation":"Total mass is 100 g, so protein is 24/100×100=24%."},{"id":"bio-sup-w04-concept","week":4,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Enzymes & Reaction Rates","prompt":"Which statement best describes enzyme action?","options":["Enzymes speed reactions by lowering activation-energy barriers without being consumed overall.","Enzymes increase reaction rate by permanently raising product energy.","Enzymes are used up after one reaction.","Every enzyme works best at the same temperature and pH."],"answer":0,"explanation":"Enzymes lower activation-energy barriers and are not consumed overall."},{"id":"bio-sup-w04-evidence","week":4,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Enzymes & Reaction Rates","prompt":"Which experiment best tests how temperature affects enzyme activity?","options":["Measure reaction rate across several temperatures while holding enzyme amount, substrate, pH, and time constant.","Change temperature and pH together.","Measure product once at one temperature.","Compare two different enzymes at different substrate concentrations."],"answer":0,"explanation":"Varying temperature alone while controlling other factors isolates its effect on enzyme rate."},{"id":"bio-sup-w04-model","week":4,"type":"model","difficulty":"core","source":"H1-model","topic":"Enzymes & Reaction Rates","prompt":"Which statement correctly limits the idea of an enzyme 'optimum'?","options":["The optimum depends on the specific enzyme and experimental conditions rather than being universal.","All enzymes have the same optimum temperature.","An enzyme stops functioning permanently after any temperature change.","The highest measured rate always proves the enzyme is undamaged."],"answer":0,"explanation":"Enzyme optima are condition- and enzyme-specific and should not be generalized universally."},{"id":"bio-sup-w05-concept","week":5,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Cell Theory & Cellular Organization","prompt":"Which statement best reflects modern cell theory?","options":["Cells are fundamental structural and functional units of life, and new cells arise from existing cells.","All cells contain exactly the same organelles.","Only multicellular organisms are made of cells.","Cells can arise spontaneously from nonliving material."],"answer":0,"explanation":"Cell theory identifies cells as fundamental units of life and rejects spontaneous generation."},{"id":"bio-sup-w05-evidence","week":5,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Cell Theory & Cellular Organization","prompt":"Which observation most directly supports cell theory across diverse organisms?","options":["Microscopy repeatedly reveals cellular organization in tissues and unicellular organisms.","One large organism has many tissues.","Cells vary in size and shape.","Some cells lack nuclei."],"answer":0,"explanation":"Repeated microscopic evidence across diverse organisms directly supports cellular organization as a shared feature of life."},{"id":"bio-sup-w05-model","week":5,"type":"model","difficulty":"core","source":"H1-model","topic":"Cell Theory & Cellular Organization","prompt":"Which statement correctly limits cell theory?","options":["Cell theory does not require every cell to have the same organelles, size, or specialization.","Every cell must contain a nucleus.","All cells perform identical functions.","Cell theory applies only to animals and plants."],"answer":0,"explanation":"Cell theory describes shared cellular organization without implying identical structure or specialization."},{"id":"bio-sup-w05-quantitative","week":5,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Cell Theory & Cellular Organization","prompt":"A micrograph scale bar representing 10 μm measures 2 cm on paper. A cell spans 5 cm. Estimated cell length?","options":["25 μm","5 μm","20 μm","50 μm"],"answer":0,"explanation":"The cell is 5/2=2.5 times the scale bar, so 2.5×10 μm=25 μm."},{"id":"bio-sup-w06-concept","week":6,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Membranes, Transport & Surface Area","prompt":"Which statement best describes selective membrane transport?","options":["Membranes regulate movement using permeability, gradients, and transport proteins.","All molecules cross membranes equally easily.","Diffusion requires ATP in every case.","At equilibrium, particles stop moving."],"answer":0,"explanation":"Membrane transport depends on selective permeability, gradients, and transport mechanisms; equilibrium is dynamic."},{"id":"bio-sup-w06-evidence","week":6,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Membranes, Transport & Surface Area","prompt":"Which experiment best tests an osmosis model?","options":["Measure mass change of identical membrane-bound samples placed in solutions of different solute concentration.","Measure color differences between unrelated cells.","Count chromosomes before and after soaking tissue in water.","Change both temperature and solution concentration at the same time with no controls."],"answer":0,"explanation":"Controlled mass change across concentration conditions directly tests water movement by osmosis."},{"id":"bio-sup-w07-concept","week":7,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Organelles, Energy Systems & Endosymbiosis","prompt":"Which observation is central to the endosymbiotic model of mitochondria and chloroplasts?","options":["They retain bacterial-like features such as circular DNA and ribosomes.","They are the largest structures in every cell.","They contain the cell's nuclear chromosomes.","They can live indefinitely outside the cell."],"answer":0,"explanation":"Multiple bacterial-like features support an endosymbiotic origin."},{"id":"bio-sup-w07-evidence","week":7,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Organelles, Energy Systems & Endosymbiosis","prompt":"Which evidence combination most strongly supports endosymbiosis?","options":["Circular DNA, bacterial-like ribosomes, double membranes, and phylogenetic similarity to bacteria","Organelle color and cell size alone","Presence only in multicellular organisms","Location near the nucleus in some cells"],"answer":0,"explanation":"Converging structural, molecular, and phylogenetic evidence strongly supports endosymbiotic ancestry."},{"id":"bio-sup-w07-model","week":7,"type":"model","difficulty":"core","source":"H1-model","topic":"Organelles, Energy Systems & Endosymbiosis","prompt":"Which statement correctly limits the endosymbiotic model?","options":["It explains organelle origins but does not imply modern mitochondria or chloroplasts are independent organisms.","It predicts mitochondria can survive indefinitely without host cells.","It means all organelles originated by endosymbiosis.","It proves every eukaryotic cell has chloroplasts."],"answer":0,"explanation":"Endosymbiosis explains origins of particular organelles without implying modern independence or universal chloroplast presence."},{"id":"bio-sup-w07-quantitative","week":7,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Organelles, Energy Systems & Endosymbiosis","prompt":"Cell A contains 600 mitochondria and uses 3× as much oxygen per minute as Cell B with 200 mitochondria. Which comparison is most defensible?","options":["The cells have the same oxygen use per mitochondrion in this simplified comparison.","Cell A uses three times more oxygen per mitochondrion.","Cell B uses three times more oxygen per mitochondrion.","Mitochondrial number alone proves causation."],"answer":0,"explanation":"Both oxygen use and mitochondrial number differ by a factor of three, so the normalized rate is equal in this simplified comparison."},{"id":"bio-sup-w08-concept","week":8,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Cell Specialization, Tissues & Systems","prompt":"Why can two cell types in one organism have different structures and functions despite similar genomes?","options":["They express different sets of genes and proteins.","Each cell type usually has a completely different genome.","Cell shape determines DNA sequence.","Ribosomes permanently delete unused genes."],"answer":0,"explanation":"Differential gene expression produces distinct cell structures and functions from largely shared genomes."},{"id":"bio-sup-w08-evidence","week":8,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Cell Specialization, Tissues & Systems","prompt":"Which observation best supports differential gene expression as a basis for specialization?","options":["Two cell types have similar DNA but different RNA and protein profiles.","Two tissues have different colors.","One cell is larger than another.","Every gene is expressed equally in all tissues."],"answer":0,"explanation":"Similar genomes paired with different expression profiles directly support differential gene expression."},{"id":"bio-sup-w08-model","week":8,"type":"model","difficulty":"core","source":"H1-model","topic":"Cell Specialization, Tissues & Systems","prompt":"Which statement correctly limits a cell-specialization model?","options":["Specialized cells share many genes but do not express every gene at the same level.","Specialization requires permanent loss of most genes.","A cell's function is determined only by its shape.","All specialized cells become genetically unrelated."],"answer":0,"explanation":"Specialization largely reflects regulated expression, not wholesale genome loss."},{"id":"bio-sup-w08-quantitative","week":8,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Cell Specialization, Tissues & Systems","prompt":"A tissue sample contains 120 cells, 30 of which are a specialized type. What proportion of the sample is that cell type?","options":["25%","30%","40%","75%"],"answer":0,"explanation":"30/120×100=25%."},{"id":"bio-sup-w09-concept","week":9,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Photosynthesis: Capturing Energy","prompt":"Which statement best describes photosynthesis?","options":["It converts light energy into chemical energy while incorporating carbon dioxide into organic molecules.","Plants obtain most of their dry biomass directly from soil minerals.","Photosynthesis creates carbon atoms.","Photosynthesis occurs only at night."],"answer":0,"explanation":"Photosynthesis stores light energy in chemical form and fixes carbon from CO₂."},{"id":"bio-sup-w09-evidence","week":9,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Photosynthesis: Capturing Energy","prompt":"Which result most directly tests whether light intensity limits photosynthesis?","options":["Measure photosynthetic rate across controlled light intensities while holding other major variables constant.","Compare two plant species grown under different light, temperature, and water conditions.","Measure leaf color once.","Count roots without measuring photosynthetic output."],"answer":0,"explanation":"Varying light intensity while controlling other variables directly tests its effect on photosynthetic rate."},{"id":"bio-sup-w09-model","week":9,"type":"model","difficulty":"core","source":"H1-model","topic":"Photosynthesis: Capturing Energy","prompt":"Which statement corrects a common misconception about plant biomass?","options":["Much of plant carbon comes from atmospheric carbon dioxide, not directly from soil mass.","Most plant dry mass comes from absorbed soil minerals.","Photosynthesis creates matter from light alone.","Roots convert soil into plant tissue without carbon fixation."],"answer":0,"explanation":"Carbon dioxide supplies much of the carbon incorporated into plant biomass."},{"id":"bio-sup-w10-concept","week":10,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Cellular Respiration & ATP","prompt":"Which statement best describes cellular respiration?","options":["It transfers chemical energy from fuels into ATP through coupled biochemical pathways.","It is identical to breathing.","It creates energy from nothing.","It occurs only in animals."],"answer":0,"explanation":"Cellular respiration transforms chemical energy into ATP and occurs broadly across organisms."},{"id":"bio-sup-w10-evidence","week":10,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Cellular Respiration & ATP","prompt":"Which measurement most directly indicates aerobic cellular respiration rate?","options":["Oxygen consumption or carbon dioxide production per unit time under controlled conditions","Leaf color alone","Chromosome number","Cell diameter without metabolic data"],"answer":0,"explanation":"Oxygen use and CO₂ production are direct metabolic indicators of aerobic respiration."},{"id":"bio-sup-w11-concept","week":11,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Matter Cycling Through Metabolism","prompt":"Which statement best distinguishes matter cycling from energy flow in metabolism?","options":["Atoms are rearranged and conserved through metabolic pathways while usable energy is transformed and dissipated.","Energy and matter are both recycled indefinitely in the same way.","Atoms disappear when fuels are oxidized.","Cells create new matter whenever ATP is produced."],"answer":0,"explanation":"Matter is conserved and rearranged, whereas usable energy is transformed and ultimately dissipated."},{"id":"bio-sup-w11-evidence","week":11,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Matter Cycling Through Metabolism","prompt":"Which evidence would most directly track carbon through connected metabolic pathways?","options":["A labeled-carbon tracer followed through reactants and products","A color change with no chemical identification","A single ATP measurement with no carbon data","Cell size measured before and after metabolism"],"answer":0,"explanation":"A labeled-carbon tracer directly follows carbon atoms through connected reactions."},{"id":"bio-sup-w11-model","week":11,"type":"model","difficulty":"core","source":"H1-model","topic":"Matter Cycling Through Metabolism","prompt":"Which statement correctly limits a simplified metabolism model?","options":["Matter conservation does not mean energy is recycled indefinitely; energy quality degrades as transformations occur.","Energy can be reused forever without loss.","Matter disappears whenever heat is released.","Atom balances can prove every biochemical mechanism."],"answer":0,"explanation":"Matter and energy require different accounting: atoms are conserved, while usable energy dissipates."},{"id":"bio-sup-w12-concept","week":12,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Experimental Energetics & Metabolic Evidence","prompt":"Which design feature is most important for a strong metabolic experiment?","options":["A control condition, repeated trials, defined variables, and quantitative rate measurements","One treatment group with no comparison","Changing several variables at once","Selecting only trials that match the prediction"],"answer":0,"explanation":"Controls, replication, defined variables, and quantitative measurements support causal interpretation."},{"id":"bio-sup-w12-evidence","week":12,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Experimental Energetics & Metabolic Evidence","prompt":"A treatment group has a mean respiration rate of 8.1±0.3 units and a control has 5.0±0.4. Which interpretation is strongest?","options":["The treatment is associated with a substantially higher rate relative to the observed trial variation.","The treatment proves a molecular mechanism by itself.","The difference should be ignored because the means are not identical across trials.","The control is unnecessary because the treatment mean is larger."],"answer":0,"explanation":"The separation relative to observed variation supports a treatment effect, but mechanism still requires additional evidence."},{"id":"bio-sup-w12-model","week":12,"type":"model","difficulty":"core","source":"H1-model","topic":"Experimental Energetics & Metabolic Evidence","prompt":"Which statement correctly limits interpretation of a correlation between two metabolic measurements?","options":["Correlation can support association but does not by itself establish a causal mechanism.","A strong correlation proves one variable causes the other.","Correlation eliminates the need for controls.","If two variables rise together, no third factor can matter."],"answer":0,"explanation":"Correlation alone cannot establish causation or exclude confounding variables."},{"id":"bio-sup-w12-quantitative","week":12,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Experimental Energetics & Metabolic Evidence","prompt":"A metabolic rate rises from 20 to 30 units/min. What is the percent increase relative to the original rate?","options":["50%","10%","33%","150%"],"answer":0,"explanation":"(30−20)/20×100=50%."},{"id":"bio-sup-w13-concept","week":13,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Cell Communication","prompt":"Which sequence best describes a typical cell-signaling pathway?","options":["Signal reception → intracellular transduction → cellular response","DNA replication → mitosis → osmosis","ATP production → chromosome separation → translation","Diffusion → meiosis → gene deletion"],"answer":0,"explanation":"Cell signaling commonly proceeds through reception, transduction, and response."},{"id":"bio-sup-w13-evidence","week":13,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Cell Communication","prompt":"Which experiment most directly tests whether a receptor is required for a signaling response?","options":["Disrupt the receptor and compare the response with a matched control after the same signal exposure","Increase signal concentration without measuring receptor function","Measure receptor abundance once with no response data","Compare two unrelated cell types under different conditions"],"answer":0,"explanation":"A receptor perturbation with matched signaling conditions directly tests receptor requirement."},{"id":"bio-sup-w13-model","week":13,"type":"model","difficulty":"core","source":"H1-model","topic":"Cell Communication","prompt":"Which statement correctly limits a simple cell-signaling model?","options":["A signal can act through a surface receptor without entering the target cell, and pathway responses can depend on context.","Every signaling molecule must enter the nucleus.","All cells respond identically to the same signal.","A dose-response curve alone proves the full molecular pathway."],"answer":0,"explanation":"Receptor-mediated signaling can transmit information without signal entry, and response depends on cellular context."},{"id":"bio-sup-w14-concept","week":14,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Feedback & Homeostasis","prompt":"Which statement best describes biological homeostasis?","options":["Regulatory systems use feedback to keep variables within functional ranges despite disturbances.","Internal conditions never change.","Negative feedback always amplifies deviations.","Homeostasis requires every variable to remain at one exact value."],"answer":0,"explanation":"Homeostasis is dynamic regulation around functional ranges, often through negative feedback."},{"id":"bio-sup-w14-evidence","week":14,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Feedback & Homeostasis","prompt":"Which pattern most strongly supports negative feedback after a disturbance?","options":["A regulated variable deviates from its range and then moves back toward baseline over time","The variable continues moving farther from baseline","The variable changes once and is never measured again","The variable remains displaced with no corrective response"],"answer":0,"explanation":"A return toward baseline after disturbance is consistent with negative feedback."},{"id":"bio-sup-w14-model","week":14,"type":"model","difficulty":"core","source":"H1-model","topic":"Feedback & Homeostasis","prompt":"Which statement correctly limits a homeostasis model?","options":["Regulated variables can fluctuate within dynamic ranges; homeostasis does not mean perfect constancy.","A healthy system never allows any variation.","All feedback loops are negative.","Homeostasis can be inferred from one isolated measurement."],"answer":0,"explanation":"Homeostasis permits regulated fluctuation and should be evaluated over time, not from one value."},{"id":"bio-sup-w15-concept","week":15,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Cell Cycle, Mitosis & Growth","prompt":"Which statement correctly describes mitosis?","options":["It usually produces two genetically similar daughter cells while maintaining chromosome number.","It produces four genetically varied haploid gametes.","It halves chromosome number in somatic growth.","It is the main source of independent assortment."],"answer":0,"explanation":"Mitosis generally maintains chromosome number and produces two similar daughter cells."},{"id":"bio-sup-w15-evidence","week":15,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Cell Cycle, Mitosis & Growth","prompt":"Which evidence would best estimate how much time cells spend in different cell-cycle stages?","options":["Count many cells in each stage from a representative sample and compare stage frequencies","Observe one dividing cell","Count chromosomes in one nucleus only","Measure cell color without identifying stages"],"answer":0,"explanation":"Stage frequencies across many cells can estimate relative time spent in stages under steady-state assumptions."},{"id":"bio-sup-w16-concept","week":16,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Cell-Cycle Regulation & Model Boundaries","prompt":"Which statement best describes cell-cycle checkpoints?","options":["They integrate molecular signals about DNA integrity, cell state, and conditions before progression.","They are one permanent on/off switch.","They function only during mitosis.","They guarantee damaged cells can never divide."],"answer":0,"explanation":"Cell-cycle checkpoints are coordinated regulatory systems that integrate multiple signals."},{"id":"bio-sup-w16-evidence","week":16,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Cell-Cycle Regulation & Model Boundaries","prompt":"Which result most strongly supports a checkpoint-regulation defect?","options":["Disrupting a checkpoint regulator increases proliferation despite persistent DNA damage","Cells slow division after damage","A treatment changes cell color but not division","A regulator is present but no functional change is measured"],"answer":0,"explanation":"Continued proliferation despite damage after checkpoint disruption supports regulatory failure."},{"id":"bio-sup-w16-model","week":16,"type":"model","difficulty":"core","source":"H1-model","topic":"Cell-Cycle Regulation & Model Boundaries","prompt":"Which statement correctly limits a simplified checkpoint model?","options":["Cell-cycle control involves interacting regulators and pathways rather than a single switch.","One checkpoint protein alone determines every cell-cycle decision.","Checkpoint activation always causes permanent cell death.","All tissues use identical checkpoint responses."],"answer":0,"explanation":"Checkpoint control is networked and context-dependent rather than governed by one universal switch."},{"id":"bio-sup-w16-quantitative","week":16,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Cell-Cycle Regulation & Model Boundaries","prompt":"A cell line divides 18 times per 100 observed cells before a perturbation and 30 times per 100 afterward. What is the percent increase in division frequency?","options":["66.7%","12%","40%","166.7%"],"answer":0,"explanation":"(30−18)/18×100≈66.7%."},{"id":"bio-sup-w17-concept","week":17,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Semester Synthesis Investigation","prompt":"Which statement best describes a strong semester synthesis in Biology?","options":["It connects evidence across molecular, cellular, energetic, and regulatory scales while preserving assumptions and limitations.","It replaces all unit-specific evidence with one broad claim.","It requires every dataset to show the same pattern.","It treats one memorized definition as sufficient synthesis."],"answer":0,"explanation":"Strong synthesis connects multiple scales and evidence types without erasing limits or differences."},{"id":"bio-sup-w17-evidence","week":17,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Semester Synthesis Investigation","prompt":"Which evidence strategy most strengthens a cross-unit biological synthesis?","options":["Use multiple independent datasets and explain where they converge, differ, or have different uncertainty","Use only the dataset that best fits the preferred conclusion","Average unrelated quantities together","Ignore contradictory evidence to keep the model simple"],"answer":0,"explanation":"Independent converging evidence strengthens synthesis while discrepancies and uncertainty must remain visible."},{"id":"bio-sup-w17-model","week":17,"type":"model","difficulty":"core","source":"H1-model","topic":"Semester Synthesis Investigation","prompt":"Which statement correctly limits a unifying biological model?","options":["A synthesis model should preserve exceptions, uncertainty, and domain limits instead of claiming universal fit.","A useful model must explain every biological case without exception.","Once a model fits one dataset, revision is unnecessary.","Model limitations should be removed from the final explanation."],"answer":0,"explanation":"Unifying models remain bounded by evidence, assumptions, uncertainty, and scope."},{"id":"bio-sup-w17-quantitative","week":17,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Semester Synthesis Investigation","prompt":"Dataset A changes from 10 to 15 units and Dataset B from 40 to 50. Which shows the larger percent increase?","options":["Dataset A, 50% versus 25% for Dataset B","Dataset B, because its absolute increase is larger","They are equal because both increase","Cannot compare percent changes across datasets"],"answer":0,"explanation":"A increases 5/10=50%, while B increases 10/40=25%."},{"id":"bio-sup-w18-concept","week":18,"type":"concept","difficulty":"core","source":"H1-concept","topic":"Midterm Examination & Corrections","prompt":"What is the strongest purpose of midterm correction work?","options":["Identify the reasoning error, rebuild the underlying model, and document the correction.","Copy the correct answer without explaining why.","Erase the original mistake so it is no longer visible.","Memorize the missed item wording for the next attempt."],"answer":0,"explanation":"Correction work should diagnose and repair reasoning rather than reproduce an answer."},{"id":"bio-sup-w18-evidence","week":18,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Midterm Examination & Corrections","prompt":"Which evidence best identifies a student's remediation priority after a midterm?","options":["A repeated pattern of errors across the same reasoning domain","One isolated missed item with no pattern","The visual length of the questions","Only the student's overall score with no domain breakdown"],"answer":0,"explanation":"Patterns across related errors provide stronger remediation evidence than one isolated miss."},{"id":"bio-sup-w18-model","week":18,"type":"model","difficulty":"core","source":"H1-model","topic":"Midterm Examination & Corrections","prompt":"Which practice preserves assessment integrity during public midterm review?","options":["Use parallel public review problems while keeping official exam questions and answer keys protected.","Post the official answer key publicly.","Reuse protected exam questions as open practice.","Let students copy exact protected items into shared notes."],"answer":0,"explanation":"Public remediation should remain separate from protected assessment content."},{"id":"bio-sup-w18-quantitative","week":18,"type":"quantitative","difficulty":"core","source":"H1-quantitative","topic":"Midterm Examination & Corrections","prompt":"A student misses 6 of 20 quantitative-reasoning items and 2 of 20 evidence-reasoning items. Which domain needs more remediation by error rate?","options":["Quantitative reasoning at 30% error versus evidence reasoning at 10%","Evidence reasoning because 2 is smaller than 6","They are equal because both domains had 20 items","Cannot compare domain error rates"],"answer":0,"explanation":"6/20=30% and 2/20=10%, so quantitative reasoning has the higher error rate."},{"id":"bio-sup-w18-correction","week":18,"type":"evidence","difficulty":"core","source":"H1-evidence","topic":"Midterm Examination & Corrections","prompt":"Which public review action best supports genuine midterm correction without exposing protected exam content?","options":["Classify the reasoning error, rebuild the model, and document the correction","Copy the official answer key into public notes","Memorize the missed item without explaining the reasoning","Delete the original mistake from the learning record"],"answer":0,"explanation":"Correction quality comes from diagnosing and repairing reasoning while protected assessment content remains separate."},{"id":"bio-sup-w19-concept","week":19,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Meiosis & Sources of Variation","prompt":"Which process is a major source of genetic variation during meiosis?","options":["Independent assortment and crossing over","DNA replication producing identical sister chromatids only","Mitosis in somatic cells","Removal of all homologous chromosomes"],"answer":0,"explanation":"Independent assortment and crossing over generate new combinations during meiosis."},{"id":"bio-sup-w19-evidence","week":19,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Meiosis & Sources of Variation","prompt":"Which observation best supports a model that meiosis generates genetic variation?","options":["Gametes or offspring show combinations not identical to either parental homolog set","Every gamete has the same allele combination","Chromosome number doubles in gametes","Crossing over never occurs"],"answer":0,"explanation":"Novel gamete combinations support variation generated by meiotic processes."},{"id":"bio-sup-w19-model","week":19,"type":"model","difficulty":"core","source":"H2-model","topic":"Meiosis & Sources of Variation","prompt":"Which statement correctly limits a simplified meiosis-variation model?","options":["Meiosis increases possible combinations but does not guarantee every gamete is unique.","Every gamete produced by meiosis must be genetically unique.","Independent assortment creates no variation.","Crossing over always occurs at the same loci."],"answer":0,"explanation":"Meiosis expands variation probabilistically without guaranteeing uniqueness for every gamete."},{"id":"bio-sup-w20-concept","week":20,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Mendelian Inheritance","prompt":"Which statement best describes Mendelian inheritance in a simple monohybrid cross?","options":["Alleles segregate into gametes and recombine probabilistically at fertilization.","Dominant alleles are always more common in populations.","Recessive alleles disappear when a dominant allele is present.","Punnett squares guarantee exact outcomes in small families."],"answer":0,"explanation":"Mendelian models describe allele segregation and probabilistic genotype combinations."},{"id":"bio-sup-w20-evidence","week":20,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Mendelian Inheritance","prompt":"Which evidence most directly tests a simple Mendelian inheritance prediction?","options":["Compare observed offspring genotype or phenotype counts with predicted proportions across a sufficiently large sample.","Observe one offspring only.","Assume the Punnett square must be exact.","Count parental body size without offspring data."],"answer":0,"explanation":"Observed offspring distributions can be compared with probabilistic Mendelian expectations."},{"id":"bio-sup-w20-model","week":20,"type":"model","difficulty":"core","source":"H2-model","topic":"Mendelian Inheritance","prompt":"Which statement correctly limits interpretation of a 3:1 Mendelian prediction?","options":["It is an expected probability ratio and small samples can deviate by chance.","Every group of four offspring must contain exactly three dominant and one recessive.","A 3:1 ratio proves only one gene influences the trait.","Any deviation means Mendel's laws are false."],"answer":0,"explanation":"Mendelian ratios are probabilistic expectations, not fixed outcomes for small samples."},{"id":"bio-sup-w21-concept","week":21,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Probability, Pedigrees & Statistical Reasoning","prompt":"Which statement best describes how probability and pedigrees should be used together?","options":["Use probability to evaluate inheritance hypotheses while recognizing pedigree evidence is uncertain and assumption-dependent.","A pedigree always proves one inheritance mechanism.","Probability is unnecessary if a family tree is available.","One affected relative determines every descendant's genotype."],"answer":0,"explanation":"Pedigree interpretation combines probabilistic reasoning with assumptions and uncertain evidence."},{"id":"bio-sup-w21-evidence","week":21,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Probability, Pedigrees & Statistical Reasoning","prompt":"Which evidence would most strongly distinguish between competing inheritance models in a pedigree?","options":["A larger pedigree with repeated inheritance patterns across generations","One affected individual with no family context","A pedigree interpreted without considering penetrance or sampling","A single genotype probability treated as proof of the family mechanism"],"answer":0,"explanation":"Broader repeated inheritance patterns provide stronger evidence for distinguishing candidate models."},{"id":"bio-sup-w21-model","week":21,"type":"model","difficulty":"core","source":"H2-model","topic":"Probability, Pedigrees & Statistical Reasoning","prompt":"Which statement best describes a limitation of pedigree-based inheritance models?","options":["A pedigree can be informative but may not uniquely identify a mechanism without assumptions about penetrance, mating, and sampling.","A pedigree always reveals the exact causal gene.","Unaffected individuals can never carry a recessive allele.","One small family is sufficient to prove a universal inheritance pattern."],"answer":0,"explanation":"Pedigree interpretation depends on assumptions and sample structure and rarely proves one mechanism by itself."},{"id":"bio-sup-w21-quantitative","week":21,"type":"quantitative","difficulty":"core","source":"H2-quantitative","topic":"Probability, Pedigrees & Statistical Reasoning","prompt":"Two independent inheritance events have probabilities 1/2 and 1/3. What is the probability that both occur?","options":["1/6","5/6","1/2","2/3"],"answer":0,"explanation":"For independent events that must both occur, multiply: 1/2×1/3=1/6."},{"id":"bio-sup-w22-concept","week":22,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Complex Traits & Gene–Environment Interaction","prompt":"Which statement best describes complex traits?","options":["They can reflect many genes, environmental influences, and gene–environment interactions.","They are always controlled by one dominant allele.","Environment has no effect if a trait is heritable.","One genotype guarantees one fixed phenotype in every environment."],"answer":0,"explanation":"Complex traits often arise from polygenic and environmental contributions."},{"id":"bio-sup-w22-evidence","week":22,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Complex Traits & Gene–Environment Interaction","prompt":"Which result most strongly supports a gene–environment interaction for a quantitative trait?","options":["Different genotypes change phenotype differently across the same environmental gradient","All genotypes shift by exactly the same amount in every environment","A trait differs between two people measured in only one environment","One genotype has a higher mean with no environmental comparison"],"answer":0,"explanation":"Different genotype responses across environments support interaction rather than a simple additive effect."},{"id":"bio-sup-w22-model","week":22,"type":"model","difficulty":"core","source":"H2-model","topic":"Complex Traits & Gene–Environment Interaction","prompt":"Which statement correctly limits the interpretation of heritability?","options":["High heritability in one population does not mean the trait is fixed or unaffected by environment.","High heritability means environment has no influence.","Heritability predicts an individual's outcome with certainty.","Heritability is identical in every population and environment."],"answer":0,"explanation":"Heritability is population- and environment-specific and does not imply immutability or individual certainty."},{"id":"bio-sup-w23-concept","week":23,"type":"concept","difficulty":"core","source":"H2-concept","topic":"DNA Structure & Replication","prompt":"Which statement best describes semiconservative DNA replication?","options":["Each daughter DNA molecule contains one parental strand and one newly synthesized strand.","Both parental strands stay together in one daughter molecule.","DNA replication produces RNA instead of DNA.","The parental DNA is destroyed before copying."],"answer":0,"explanation":"Semiconservative replication retains one old strand in each daughter DNA molecule."},{"id":"bio-sup-w23-evidence","week":23,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"DNA Structure & Replication","prompt":"Which evidence most directly supports semiconservative DNA replication?","options":["New DNA molecules contain one parental strand paired with one newly synthesized strand","Each daughter molecule contains two entirely old strands","Replication produces RNA instead of DNA","Chromosomes disappear and are rebuilt from proteins"],"answer":0,"explanation":"Semiconservative replication predicts one old and one newly synthesized strand in each daughter DNA molecule."},{"id":"bio-sup-w23-model","week":23,"type":"model","difficulty":"core","source":"H2-model","topic":"DNA Structure & Replication","prompt":"Which statement is an important limitation of the simplified DNA replication model?","options":["Replication is highly accurate but still permits occasional errors and repair events.","Replication is perfectly error-free under all conditions.","Complementary base pairing makes enzymes unnecessary.","Both parental strands are destroyed after copying."],"answer":0,"explanation":"DNA replication is highly accurate but not perfectly error-free and depends on enzyme systems and repair."},{"id":"bio-sup-w24-concept","week":24,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Transcription, Translation & the Genetic Code","prompt":"Which statement correctly links transcription and translation?","options":["DNA sequence is transcribed into RNA, which can be translated into a polypeptide sequence.","DNA is translated directly by ribosomes without RNA.","Proteins are transcribed into DNA.","Every gene produces exactly one unmodified final protein."],"answer":0,"explanation":"Gene expression commonly links DNA → RNA → polypeptide, with regulation and processing able to modify outcomes."},{"id":"bio-sup-w24-evidence","week":24,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Transcription, Translation & the Genetic Code","prompt":"Which observation best supports the link between codon sequence and protein sequence?","options":["A defined nucleotide substitution changes a codon and predictably changes the encoded amino acid","Every mutation always changes an amino acid","Protein sequence can change without any change in RNA or translation","Codon order is unrelated to amino-acid order"],"answer":0,"explanation":"A sequence change that predictably alters a codon and amino-acid output directly tests the genetic-code model."},{"id":"bio-sup-w25-concept","week":25,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Gene Regulation & Epigenetic Mechanisms","prompt":"Which statement best describes gene regulation?","options":["Cells can change when and how strongly genes are expressed without changing the underlying DNA sequence.","Gene regulation requires deleting genes.","Every expression change is a permanent mutation.","All genes are expressed equally in every cell."],"answer":0,"explanation":"Gene regulation changes expression patterns without requiring sequence change."},{"id":"bio-sup-w25-evidence","week":25,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Gene Regulation & Epigenetic Mechanisms","prompt":"Which experiment most directly tests whether a regulatory element changes gene expression?","options":["Perturb the regulatory element and compare expression with an appropriate control","Measure expression once with no comparison condition","Assume any expression difference is caused by DNA mutation","Compare two unrelated genes in different tissues without controls"],"answer":0,"explanation":"A controlled perturbation followed by expression measurement directly tests regulatory function."},{"id":"bio-sup-w25-model","week":25,"type":"model","difficulty":"core","source":"H2-model","topic":"Gene Regulation & Epigenetic Mechanisms","prompt":"Which statement correctly distinguishes epigenetic regulation from DNA-sequence mutation?","options":["Epigenetic marks can alter gene activity without changing the underlying nucleotide sequence.","Every epigenetic change permanently rewrites the DNA sequence.","Epigenetic regulation means genes are removed from the chromosome.","Epigenetic marks always pass unchanged through every generation."],"answer":0,"explanation":"Epigenetic regulation can alter expression without changing nucleotide sequence and is not necessarily permanent or inherited."},{"id":"bio-sup-w26-concept","week":26,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Biotechnology, Genomics & Bioethics","prompt":"Which statement best describes biotechnology and genomics?","options":["They use biological systems or molecular tools to measure, analyze, or modify biological information.","A technique is scientifically valid merely because it is technologically powerful.","Genomic results require no controls or reference samples.","Genetic data have no privacy or consent implications."],"answer":0,"explanation":"Biotechnology/genomics combine biological tools with evidence standards and ethical responsibilities."},{"id":"bio-sup-w26-evidence","week":26,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Biotechnology, Genomics & Bioethics","prompt":"Which evidence practice most strengthens a biotechnology result?","options":["Use appropriate positive/negative controls, reference samples, replication, and reproducible output.","Report only the strongest-looking result.","Omit controls if the expected signal appears.","Treat one successful run as definitive."],"answer":0,"explanation":"Controls, references, and reproducibility are central to evaluating biotechnology results."},{"id":"bio-sup-w26-model","week":26,"type":"model","difficulty":"core","source":"H2-model","topic":"Biotechnology, Genomics & Bioethics","prompt":"Which statement correctly limits conclusions from a powerful biotechnology technique?","options":["Technical capability does not by itself make every application scientifically justified or ethically acceptable.","If a technique works, consent is unnecessary.","High sensitivity means false positives are impossible.","A technically possible intervention is automatically the best scientific choice."],"answer":0,"explanation":"Scientific validity, uncertainty, privacy, consent, and ethics remain relevant regardless of technical power."},{"id":"bio-sup-w27-concept","week":27,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Evidence for Evolutionary Change","prompt":"Which statement best summarizes how evolutionary relationships are supported scientifically?","options":["Multiple independent evidence streams can converge on compatible evolutionary relationships.","One fossil is sufficient to prove an entire lineage history.","Molecular evidence should be ignored when morphology is available.","Evolutionary relationships are ranked from lower to higher forms."],"answer":0,"explanation":"Converging evidence from fossils, comparative biology, genetics, and observed populations strengthens evolutionary inference."},{"id":"bio-sup-w27-evidence","week":27,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Evidence for Evolutionary Change","prompt":"Which evidence pattern most strongly supports a proposed evolutionary relationship?","options":["Independent fossil, anatomical, and molecular evidence that converge on the same branching pattern","One similarity shared by unrelated species with no additional evidence","A single diagram repeated in several textbooks","A trait chosen only because it matches the expected conclusion"],"answer":0,"explanation":"Independent converging evidence provides stronger support than one repeated or selectively chosen observation."},{"id":"bio-sup-w27-model","week":27,"type":"model","difficulty":"core","source":"H2-model","topic":"Evidence for Evolutionary Change","prompt":"Which statement correctly limits the interpretation of evolutionary change?","options":["Populations evolve across generations; individual organisms do not genetically evolve during their own lifetimes.","Individuals evolve new inherited traits whenever they need them.","Every evolutionary change is directional progress toward complexity.","Evolution stops whenever environmental conditions are stable."],"answer":0,"explanation":"Evolutionary change is measured across populations and generations, not as need-driven genetic change within one individual."},{"id":"bio-sup-w27-quantitative","week":27,"type":"quantitative","difficulty":"core","source":"H2-quantitative","topic":"Evidence for Evolutionary Change","prompt":"Two DNA sequences are 180 bases long and differ at 18 positions. What is their percent sequence difference?","options":["10%","18%","90%","162%"],"answer":0,"explanation":"18/180 × 100 = 10% sequence difference."},{"id":"bio-sup-w28-concept","week":28,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Population Genetics & Changing Allele Frequencies","prompt":"Which statement best describes population genetics?","options":["It tracks allele and genotype frequencies across generations and how evolutionary forces change them.","It measures only the number of organisms in a habitat.","It assumes allele frequencies never change.","It describes mutations only within one individual."],"answer":0,"explanation":"Population genetics studies allele/genotype frequencies and how forces such as selection, drift, mutation, and migration change them."},{"id":"bio-sup-w28-evidence","week":28,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Population Genetics & Changing Allele Frequencies","prompt":"Which dataset would most directly test whether a population is evolving genetically?","options":["Allele-frequency measurements from the same population across multiple generations","One phenotype count from a single day","A list of species names with no frequency data","One individual's genotype measured twice"],"answer":0,"explanation":"Repeated allele-frequency measurements across generations directly test population genetic change."},{"id":"bio-sup-w28-model","week":28,"type":"model","difficulty":"core","source":"H2-model","topic":"Population Genetics & Changing Allele Frequencies","prompt":"Which statement correctly describes Hardy-Weinberg equilibrium?","options":["It is a null model with assumptions used to compare observed genotype frequencies against no-evolution expectations.","It proves that real populations never evolve.","It applies even when selection, migration, or nonrandom mating are strong.","It predicts that all alleles eventually reach equal frequency."],"answer":0,"explanation":"Hardy-Weinberg equilibrium is a conditional null model, not a universal law that populations never evolve."},{"id":"bio-sup-w29-concept","week":29,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Natural Selection & Adaptation","prompt":"Which mechanism is essential to natural selection?","options":["Heritable variation causes differences in reproductive success, shifting trait or allele frequencies over generations.","Individuals intentionally change their genes to fit the environment.","All members of a population reproduce equally.","Environmental change automatically creates the exact mutation organisms need."],"answer":0,"explanation":"Natural selection requires heritable variation and differential reproductive success."},{"id":"bio-sup-w29-evidence","week":29,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Natural Selection & Adaptation","prompt":"Which result would most strongly support natural selection acting on a trait?","options":["A heritable trait is associated with higher reproductive success and increases in frequency across generations","A trait becomes more common but is not heritable","Individuals with the trait are larger but leave the same number of offspring","The environment changes, but trait frequencies remain unchanged"],"answer":0,"explanation":"Selection is supported when heritable variation predicts reproductive success and population frequency change."},{"id":"bio-sup-w29-model","week":29,"type":"model","difficulty":"core","source":"H2-model","topic":"Natural Selection & Adaptation","prompt":"Which statement correctly limits a natural-selection explanation?","options":["Selection favors existing heritable variation; organisms do not evolve traits because they consciously need them.","Selection always produces perfect adaptation.","Selection acts only when organisms choose among traits.","Selection guarantees every beneficial allele reaches fixation."],"answer":0,"explanation":"Natural selection filters heritable variation but does not operate by conscious need or guarantee perfect outcomes."},{"id":"bio-sup-w29-quantitative","week":29,"type":"quantitative","difficulty":"core","source":"H2-quantitative","topic":"Natural Selection & Adaptation","prompt":"A genotype leaves an average of 6 surviving offspring while another leaves 4. Relative fitness of the second genotype compared with the first?","options":["0.67","1.5","2","10"],"answer":0,"explanation":"Relative fitness = 4/6 ≈ 0.67."},{"id":"bio-sup-w30-concept","week":30,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Speciation, Phylogeny & Origins Literacy","prompt":"Which statement best describes speciation?","options":["Speciation involves lineage divergence and the evolution of reproductive isolation.","Speciation is simply an increase in population size.","Any mutation instantly creates a new species.","Two populations are different species whenever they live in different places."],"answer":0,"explanation":"Speciation involves sustained lineage divergence and reproductive isolation, not mere geographic separation or one mutation."},{"id":"bio-sup-w30-evidence","week":30,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Speciation, Phylogeny & Origins Literacy","prompt":"Which evidence most strongly supports a proposed branching relationship among species?","options":["Shared derived traits supported by independent genetic data","Overall body size alone","Geographic proximity with no trait or genetic evidence","A single ancestral-looking feature shared by many unrelated groups"],"answer":0,"explanation":"Shared derived characters and independent genetic evidence provide stronger phylogenetic support."},{"id":"bio-sup-w30-model","week":30,"type":"model","difficulty":"core","source":"H2-model","topic":"Speciation, Phylogeny & Origins Literacy","prompt":"Which statement correctly limits interpretation of a phylogenetic tree?","options":["A phylogenetic tree is a testable hypothesis of relationships, not a ladder of progress.","Species at the top are more evolved than species near the bottom.","Living species shown near each other are necessarily direct ancestors and descendants.","Branch length always represents time even when the tree provides no scale."],"answer":0,"explanation":"Phylogenetic trees represent hypothesized branching relationships and should not be read as progress ladders or direct ancestry unless supported."},{"id":"bio-sup-w31-concept","week":31,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Ecosystem Energy Flow","prompt":"Which statement best describes energy flow through an ecosystem?","options":["Energy enters ecosystems, moves through trophic levels, and much is dissipated as heat while matter is recycled.","Energy is recycled indefinitely between trophic levels.","Matter disappears as organisms respire.","Predators create new energy when they consume prey."],"answer":0,"explanation":"Energy flows through ecosystems and dissipates, while matter is conserved and recycled."},{"id":"bio-sup-w31-evidence","week":31,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Ecosystem Energy Flow","prompt":"Which dataset would most directly test an energy-transfer model across trophic levels?","options":["Measured productivity or biomass-energy values for successive trophic levels","A species list with no abundance or energy data","One predator's body mass measured once","A food-web diagram with no quantitative measurements"],"answer":0,"explanation":"Quantitative productivity or energy data across trophic levels directly test transfer efficiency and energy-flow models."},{"id":"bio-sup-w31-model","week":31,"type":"model","difficulty":"core","source":"H2-model","topic":"Ecosystem Energy Flow","prompt":"Which statement correctly limits interpretation of an ecological energy pyramid?","options":["A narrower upper trophic level reflects lower available energy, not disappearance of matter.","Every ecosystem transfers exactly 10% of energy between levels.","A small upper trophic level proves matter was destroyed.","Energy and matter cycle through ecosystems in exactly the same way."],"answer":0,"explanation":"Energy pyramids represent diminishing available energy; matter remains conserved and cycles through reservoirs."},{"id":"bio-sup-w32-concept","week":32,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Biogeochemical Cycles","prompt":"Which statement best describes biogeochemical cycling?","options":["Elements move among biological, atmospheric, hydrologic, and geologic reservoirs through measurable fluxes.","Elements are used once and then permanently lost from ecosystems.","All reservoirs exchange matter at the same rate.","Only living organisms participate in biogeochemical cycles."],"answer":0,"explanation":"Biogeochemical cycles move conserved elements among multiple biotic and abiotic reservoirs."},{"id":"bio-sup-w32-evidence","week":32,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Biogeochemical Cycles","prompt":"Which evidence would best reveal where carbon is accumulating in a cycle?","options":["Repeated reservoir measurements paired with measured input and output fluxes","A single concentration measurement with no time or flux context","A diagram naming reservoirs without quantities","One organism's carbon content used to represent the whole system"],"answer":0,"explanation":"Reservoir measurements plus fluxes allow evaluation of accumulation, depletion, and movement through a cycle."},{"id":"bio-sup-w32-model","week":32,"type":"model","difficulty":"core","source":"H2-model","topic":"Biogeochemical Cycles","prompt":"Which statement is an important limitation of a simplified biogeochemical-cycle model?","options":["Different reservoirs can have very different turnover rates even when they exchange the same element.","All reservoirs have identical residence times.","A cycle diagram proves fluxes are constant through time.","Matter moves only in one direction through the cycle."],"answer":0,"explanation":"Reservoirs differ in size and flux, so turnover and residence times can vary substantially."},{"id":"bio-sup-w33-concept","week":33,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Population & Community Dynamics","prompt":"Which statement best explains why population growth usually slows as density approaches carrying capacity?","options":["Resource limitation and density-dependent interactions reduce per-capita growth as population size rises.","All individuals stop reproducing at exactly the same population size.","Carrying capacity is a fixed species property that never changes.","Population growth slows only because mutation stops."],"answer":0,"explanation":"Density-dependent limits such as resource competition and disease reduce growth as populations approach carrying capacity."},{"id":"bio-sup-w33-evidence","week":33,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Population & Community Dynamics","prompt":"Which dataset would best distinguish exponential from logistic population growth?","options":["A multi-generation time series of population size with resource or density context","One population count from a single date","A species name and habitat description","One individual's lifetime reproductive output"],"answer":0,"explanation":"A time series reveals whether growth remains proportional or slows as density increases."},{"id":"bio-sup-w33-model","week":33,"type":"model","difficulty":"core","source":"H2-model","topic":"Population & Community Dynamics","prompt":"Which statement correctly limits the use of a simple logistic-growth model?","options":["Carrying capacity and growth rate can change when environmental conditions change.","The model assumes carrying capacity is always perfectly constant in nature.","Logistic growth predicts every population follows the same exact curve.","The model proves migration and species interactions are irrelevant."],"answer":0,"explanation":"Logistic models are useful simplifications, but parameters can vary and omitted processes can matter."},{"id":"bio-sup-w34-concept","week":34,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Biodiversity, Resilience & Human Impacts","prompt":"Which statement best describes how biodiversity can contribute to ecosystem resilience?","options":["Different species and functions can respond differently to disturbance, helping maintain or restore ecosystem processes.","More species always prevent every disturbance.","Species richness alone guarantees all ecosystem functions are protected.","Biodiversity stops natural selection from occurring."],"answer":0,"explanation":"Functional and response diversity can help ecosystems maintain or recover function after disturbance."},{"id":"bio-sup-w34-evidence","week":34,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Biodiversity, Resilience & Human Impacts","prompt":"Which study design would best test whether biodiversity improves resilience?","options":["Compare post-disturbance recovery across sites that differ in biodiversity while measuring the same ecosystem functions","Count species at one undisturbed site only","Compare two sites but measure different ecosystem functions at each","Assume the site with more species is more resilient without measuring recovery"],"answer":0,"explanation":"Comparable recovery measurements across a biodiversity gradient directly test a resilience hypothesis."},{"id":"bio-sup-w34-model","week":34,"type":"model","difficulty":"core","source":"H2-model","topic":"Biodiversity, Resilience & Human Impacts","prompt":"Which statement correctly limits a biodiversity–resilience claim?","options":["High species richness can support resilience, but composition, functional diversity, disturbance type, and context also matter.","Species count alone fully predicts resilience in every ecosystem.","If diversity is high, disturbance cannot reduce ecosystem function.","All species contribute equally to every ecosystem process."],"answer":0,"explanation":"Biodiversity effects depend on functional roles, response diversity, and ecological context."},{"id":"bio-sup-w34-quantitative","week":34,"type":"quantitative","difficulty":"core","source":"H2-quantitative","topic":"Biodiversity, Resilience & Human Impacts","prompt":"A site recovers from 40 units of function immediately after disturbance to 70 units, while its pre-disturbance level was 100. What fraction of the lost function was recovered?","options":["50%","30%","70%","75%"],"answer":0,"explanation":"The site regained 30 of the 60 units lost, so recovery of lost function is 30/60 = 50%."},{"id":"bio-sup-w35-concept","week":35,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Biology & Biotechnology Capstone","prompt":"Which feature is essential to a strong Biology & Biotechnology capstone?","options":["A testable question linked to traceable evidence, quantitative analysis, a model or explanation, and explicit limitations","A polished presentation even if methods are hidden","A conclusion chosen before collecting data","Only qualitative observations with no attempt to evaluate uncertainty"],"answer":0,"explanation":"A strong capstone integrates a testable question, evidence, analysis, explanation, and limitations."},{"id":"bio-sup-w35-evidence","week":35,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Biology & Biotechnology Capstone","prompt":"Which evidence practice most strengthens a capstone claim?","options":["Traceable raw data, documented methods, repeated measurements, and explicit uncertainty","Removing results that conflict with the preferred conclusion","Reporting only the final graph with no underlying data","Treating one successful trial as sufficient proof"],"answer":0,"explanation":"Transparent methods, traceable data, replication, and uncertainty strengthen scientific claims."},{"id":"bio-sup-w35-model","week":35,"type":"model","difficulty":"core","source":"H2-model","topic":"Biology & Biotechnology Capstone","prompt":"Which statement correctly limits conclusions from a capstone model?","options":["A model should be evaluated within its assumptions, data range, and uncertainty rather than treated as universally true.","A good-looking graph proves the model is correct.","If a model fits one dataset, competing explanations can be ignored.","Model limitations should be omitted so the conclusion appears stronger."],"answer":0,"explanation":"Scientific models remain bounded by assumptions, evidence quality, and the range of conditions tested."},{"id":"bio-sup-w35-quantitative","week":35,"type":"quantitative","difficulty":"core","source":"H2-quantitative","topic":"Biology & Biotechnology Capstone","prompt":"Two capstone groups estimate the same effect: Group A reports 12±1 units and Group B reports 12±8 units. Which result is more precise?","options":["Group A, because its uncertainty interval is narrower","Group B, because a larger uncertainty means more confidence","They are equally precise because the central value is the same","Precision cannot be compared from uncertainty information"],"answer":0,"explanation":"With the same central estimate, the narrower uncertainty interval indicates greater precision."},{"id":"bio-sup-w36-concept","week":36,"type":"concept","difficulty":"core","source":"H2-concept","topic":"Comprehensive Final & Portfolio Defense","prompt":"A student is building a concept map for Comprehensive Final & Portfolio Defense. Which statement belongs at its center?","options":["Final portfolio defense should select representative evidence of biological reasoning rather than expose protected exam content.","A credible defense includes original evidence, corrections, quantitative reasoning, and honest limitations.","Portfolio volume alone does not demonstrate mastery; evidence quality and explanation matter.","Domain scores and evidence coverage can be summarized quantitatively to identify remaining gaps."],"answer":0,"explanation":"Final portfolio defense should select representative evidence of biological reasoning rather than expose protected exam content."},{"id":"bio-sup-w36-evidence","week":36,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Comprehensive Final & Portfolio Defense","prompt":"Which measurement strategy would most strongly test the explanation developed in Comprehensive Final & Portfolio Defense?","options":["A credible defense includes original evidence, corrections, quantitative reasoning, and honest limitations.","Portfolio volume alone does not demonstrate mastery; evidence quality and explanation matter.","Domain scores and evidence coverage can be summarized quantitatively to identify remaining gaps.","Final portfolio defense should select representative evidence of biological reasoning rather than expose protected exam content."],"answer":0,"explanation":"A credible defense includes original evidence, corrections, quantitative reasoning, and honest limitations."},{"id":"bio-sup-w36-model","week":36,"type":"model","difficulty":"core","source":"H2-model","topic":"Comprehensive Final & Portfolio Defense","prompt":"Which assumption or boundary is essential when interpreting Comprehensive Final & Portfolio Defense?","options":["Portfolio volume alone does not demonstrate mastery; evidence quality and explanation matter.","Domain scores and evidence coverage can be summarized quantitatively to identify remaining gaps.","Final portfolio defense should select representative evidence of biological reasoning rather than expose protected exam content.","A credible defense includes original evidence, corrections, quantitative reasoning, and honest limitations."],"answer":0,"explanation":"Portfolio volume alone does not demonstrate mastery; evidence quality and explanation matter."},{"id":"bio-sup-w36-quantitative","week":36,"type":"quantitative","difficulty":"core","source":"H2-quantitative","topic":"Comprehensive Final & Portfolio Defense","prompt":"Which quantitative measure would most strengthen an analysis of Comprehensive Final & Portfolio Defense?","options":["Domain scores and evidence coverage can be summarized quantitatively to identify remaining gaps.","Final portfolio defense should select representative evidence of biological reasoning rather than expose protected exam content.","A credible defense includes original evidence, corrections, quantitative reasoning, and honest limitations.","Portfolio volume alone does not demonstrate mastery; evidence quality and explanation matter."],"answer":0,"explanation":"Domain scores and evidence coverage can be summarized quantitatively to identify remaining gaps."},{"id":"bio-sup-w36-correction","week":36,"type":"evidence","difficulty":"core","source":"H2-evidence","topic":"Comprehensive Final & Portfolio Defense","prompt":"Which portfolio-defense choice best demonstrates final-course mastery without exposing protected final-exam content?","options":["Select representative evidence, explain the reasoning, and state limitations","Publish protected final questions and answers as evidence","Submit the largest possible number of files without commentary","Hide all corrections so the portfolio appears error-free"],"answer":0,"explanation":"A portfolio defense should use representative learner evidence, reasoning, corrections, and limitations without exposing protected exam material."}];
